//! Deterministic harness × feature matrix generator.
//!
//! Reads the real `IntegrationPort` implementations (capabilities, exposure
//! plans, package plans, runtime support, exposure names) and renders the
//! matrix + invocation examples into the marker block of `README.md`:
//!
//! ```text
//! <!-- uze-matrix:start -->
//! ... generated by this binary; do not hand-edit ...
//! <!-- uze-matrix:end -->
//! ```
//!
//! `--check` exits non-zero when README.md is stale (wired into the
//! lefthook pre-push and `make docs-harness-matrix`); without the flag it
//! rewrites README.md in place. Nothing here hardcodes a harness's
//! capability claim — every cell is derived from the code that implements
//! it, so a capability change that forgets the docs fails the push.

use std::path::PathBuf;

use uze::{
    PackageId, UzeHome,
    acquisition::{PackageSource, Provenance, ResolvedSource},
    capability::{Capability, CapabilityKind, Representation},
    integration::IntegrationPort,
    project::Resource,
    router::CompatibilityRoute,
    store::StoredPackage,
};
use uze_integrations::{
    antigravity::AntigravityIntegration, claude::ClaudeIntegration, codex::CodexIntegration,
    opencode::OpenCodeIntegration,
};

/// Planned harnesses: no `IntegrationPort` yet, so matrix cells would be
/// meaningless — listed as roadmap only, and they flip the moment they land.
const PLANNED_HARNESSES: [&str; 2] = ["Cursor CLI", "Muse"];

const MARKER_START: &str = "<!-- uze-matrix:start -->";
const MARKER_END: &str = "<!-- uze-matrix:end -->";
const README: &str = "README.md";

fn route_symbol(route: CompatibilityRoute) -> &'static str {
    match route {
        CompatibilityRoute::Native => "🟢",
        CompatibilityRoute::Adaptable => "🟡",
        CompatibilityRoute::Degraded => "🟠",
        CompatibilityRoute::Unsupported => "⚪",
    }
}

fn route_of(integration: &dyn IntegrationPort, resource: &Resource) -> CompatibilityRoute {
    integration.exposure_plan(resource).route
}

/// The disposable package root carrying flow's canonical bytes — shared by
/// every resource and the stub package so plans correlate paths.
fn pkg_root() -> PathBuf {
    let root = std::env::temp_dir().join("uze-harness-matrix-pkg");
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(root.join("skills/commit")).unwrap();
    std::fs::write(
        root.join("plugin.json"),
        r#"{"$schema":"https://agent-plugins.org/schemas/1.0.0/plugin.schema.json","name":"flow"}"#,
    )
    .unwrap();
    std::fs::write(
        root.join("skills/commit/SKILL.md"),
        "---\nname: commit\ndescription: Matrix fixture skill.\n---\n\nBody.\n",
    )
    .unwrap();
    std::fs::write(
        root.join("mcp.json"),
        r#"{"mcpServers":{"conformance":{"command":"fixture","args":[]}}}"#,
    )
    .unwrap();
    root
}

fn skill(payload: &str, name: &str) -> Resource {
    let root = pkg_root();
    Resource::from_package(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind: CapabilityKind::AgentSkill,
            representation: Representation::Standard,
            path: root.join(format!("skills/{name}/SKILL.md")),
            payload: payload.as_bytes().to_vec(),
        },
    )
}

fn mcp() -> Resource {
    let root = pkg_root();
    Resource::from_package_named(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind: CapabilityKind::Mcp,
            representation: Representation::Standard,
            path: root.join("mcp.json"),
            payload: br#"{"command":"fixture","args":[]}"#.to_vec(),
        },
        "conformance".to_owned(),
    )
}

fn capability_resource(kind: CapabilityKind, path: &str) -> Resource {
    let root = pkg_root();
    Resource::from_package(
        PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root.clone(),
        Capability {
            kind,
            representation: Representation::Standard,
            path: PathBuf::from(path),
            payload: Vec::new(),
        },
    )
}

fn stub_package() -> StoredPackage {
    let root = pkg_root();
    StoredPackage {
        id: PackageId::from_plugin_name("flow", &root.join("plugin.json")).unwrap(),
        root: root.clone(),
        manifest: root.join("plugin.json"),
        provenance: Provenance {
            requested: PackageSource::Local { path: root.clone() },
            resolved: ResolvedSource::Local { path: root },
        },
    }
}

fn package_route(integration: &dyn IntegrationPort) -> Option<CompatibilityRoute> {
    let package = stub_package();
    let skill = skill("-", "commit");
    let mcp = mcp();
    let resources: Vec<&Resource> = vec![&skill, &mcp];
    integration
        .package_exposure_plan(&package, &resources)
        .map(|plan| plan.route)
}

struct Harness {
    id: &'static str,
    integration: Box<dyn IntegrationPort>,
    /// How a human/agent invokes an exposed capability on this harness
    /// (`{name}` is the exposure candidate).
    invocation: &'static str,
}

/// Real setup state, like the L1 contract tests record before asking for
/// exposure plans: without it the integrations deliberately prefer the
/// unmanaged/adapted route, and the matrix would document the wrong
/// surface. Writes only inside the temp root.
fn mark_setup(home: &UzeHome, integration: &dyn IntegrationPort) {
    std::fs::create_dir_all(home.state_dir()).unwrap();
    uze::state::record(
        home,
        uze::state::IntegrationRecord {
            harness: integration.id().to_owned(),
            version: None,
            strategy: "harness-matrix".to_owned(),
            installed: true,
        },
    )
    .unwrap();
}

fn harnesses() -> Vec<Harness> {
    let root = std::env::temp_dir().join(format!("uze-harness-matrix-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&root);
    std::fs::create_dir_all(&root).unwrap();
    let uze_home = UzeHome::at(root.join("uze"));
    let claude = ClaudeIntegration::new(root.join("claude"), uze_home.clone());
    let codex = CodexIntegration::new(root.join("agents"), uze_home.clone());
    let opencode = OpenCodeIntegration::new(
        root.join("agents"),
        root.join("opencode-config.json"),
        uze_home.clone(),
    );
    let antigravity = AntigravityIntegration::new(root.join("agents"), uze_home.clone());
    mark_setup(&uze_home, &claude);
    mark_setup(&uze_home, &codex);
    mark_setup(&uze_home, &opencode);
    mark_setup(&uze_home, &antigravity);
    vec![
        Harness {
            id: "Claude",
            integration: Box::new(claude),
            invocation: "/{name}",
        },
        Harness {
            id: "Codex",
            integration: Box::new(codex),
            invocation: "${name}",
        },
        Harness {
            id: "OpenCode",
            integration: Box::new(opencode),
            invocation: "/{name}",
        },
        Harness {
            id: "Antigravity",
            integration: Box::new(antigravity),
            invocation: "{name}",
        },
    ]
}

/// Effective delivery route for a resource: the native package plan's route
/// when the plan both exists and covers the resource's identity, otherwise
/// the capability-level (fallback) route the integration actually uses.
fn effective_route(
    integration: &dyn IntegrationPort,
    resource: &Resource,
    fallback: CompatibilityRoute,
) -> CompatibilityRoute {
    let package = stub_package();
    if let Some(plan) = integration.package_exposure_plan(&package, &[resource])
        && plan.route == CompatibilityRoute::Native
        && plan
            .provided_resource_identities
            .contains(&resource.identity())
    {
        return CompatibilityRoute::Native;
    }
    fallback
}

fn matrix_block() -> String {
    let default_skill = skill(
        "---\nname: commit\ndescription: Matrix fixture skill.\n---\n\nBody.\n",
        "commit",
    );
    let user_only_skill = skill(
        "---\nname: review\ndescription: Matrix fixture skill.\ninvoke:\n  model: false\n  user: true\n---\n\nBody.\n",
        "review",
    );
    let mcp = mcp();
    let agents = capability_resource(CapabilityKind::Agent, "/store/flow/agents/planner.md");
    let hooks = capability_resource(CapabilityKind::Hook, "/store/flow/hooks/pre-commit.sh");

    let mut out = String::new();
    out.push_str(&format!(
        "{MARKER_START}\n\
         <!-- Generated by `cargo run --bin uze-harness-matrix`; do not hand-edit. -->\n\n\
         <table><thead>\n\
         <tr><th align=\"left\">Harness</th><th>AGENTS.md</th><th>Skill</th><th>User-only</th><th>MCP</th><th>Package</th><th>Agents</th><th>Hooks</th><th>Shim</th></tr>\n\
         </thead><tbody>\n"
    ));
    for harness in harnesses() {
        let integration = harness.integration.as_ref();
        let package = package_route(integration).map(route_symbol).unwrap_or("⚪");
        out.push_str(&format!(
            "<tr><td align=\"left\">{}</td><td>🟢</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td><td>{}</td></tr>\n",
            harness.id,
            route_symbol(effective_route(
                integration,
                &default_skill,
                route_of(integration, &default_skill),
            )),
            route_symbol(effective_route(
                integration,
                &user_only_skill,
                route_of(integration, &user_only_skill),
            )),
            route_symbol(effective_route(
                integration,
                &mcp,
                route_of(integration, &mcp)
            )),
            package,
            route_symbol(route_of(integration, &agents)),
            route_symbol(route_of(integration, &hooks)),
            if integration.supports_runtime_integration() {
                "🧪"
            } else {
                // Not a roadmap gap: the UZE runtime shim projects context
                // only where a harness has no native AGENTS.md story.
                "—"
            },
        ));
    }
    out.push_str("</tbody></table>\n");
    out.push('\n');
    out.push_str("> 🟢 native · 🟡 adapted · 🟠 degraded · ⚪ roadmap · 🧪 experimental · — n/a\n");
    out.push_str(">\n");
    out.push_str("> **Project context:** All harnesses read `AGENTS.md` natively via uze;\n");
    out.push_str("> `@AGENTS.md` bridge for Claude, native file for others.\n");
    out.push('\n');

    out.push_str("### Planned harnesses\n\n");
    out.push_str("<table><thead>\n");
    out.push_str("<tr><th align=\"left\">Harness</th><th>Status</th></tr>\n");
    out.push_str("</thead><tbody>\n");
    for planned in PLANNED_HARNESSES {
        out.push_str(&format!(
            "<tr><td align=\"left\">{planned}</td><td>⚪</td></tr>\n"
        ));
    }
    out.push_str("</tbody></table>\n");
    out.push_str("\n> ⚪ roadmap — no integration yet; cells flip when it lands.\n\n");

    // Invocation examples: canonical `flow:commit` (default policy) and
    // `workflow:review` (user-only explicit) as each harness exposes them.
    out.push_str("### Invoking a plugin\n\n");
    out.push_str(
        "`flow:commit` is model+user; `workflow:review` is user-only (never auto-invoked):\n\n\
         <table><thead>\n\
         <tr><th align=\"left\">Harness</th><th><code>flow:commit</code> (default)</th><th><code>workflow:review</code> (user-only)</th></tr>\n\
         </thead><tbody>\n",
    );
    for harness in harnesses() {
        let integration = harness.integration.as_ref();
        let default_name = integration
            .exposure_name_candidates(&default_skill)
            .into_iter()
            .next()
            .unwrap_or_else(|| "commit".to_owned());
        let user_only_name = integration
            .exposure_name_candidates(&user_only_skill)
            .into_iter()
            .next()
            .unwrap_or_else(|| "review".to_owned());
        out.push_str(&format!(
            "<tr><td align=\"left\">{}</td><td><code>{}</code></td><td><code>{}</code></td></tr>\n",
            harness.id,
            harness.invocation.replace("{name}", &default_name),
            harness.invocation.replace("{name}", &user_only_name),
        ));
    }
    out.push_str("</tbody></table>\n");
    out.push_str(&format!("\n{MARKER_END}\n"));
    out
}

fn replace_block(contents: &str, block: &str) -> String {
    let start = contents
        .find(MARKER_START)
        .expect("README.md must contain the uze-matrix marker block");
    let end = contents
        .find(MARKER_END)
        .map(|position| position + MARKER_END.len())
        .expect("README.md must close the uze-matrix marker block");
    // The block carries its own trailing `\n`; the tail after the closing
    // marker starts with the `\n` the previous generation left behind —
    // strip exactly one so repeated runs are byte-idempotent.
    let tail = &contents[end..];
    let tail = tail.strip_prefix('\n').unwrap_or(tail);
    format!("{}{}{}", &contents[..start], block, tail)
}

fn main() {
    let check = std::env::args().any(|argument| argument == "--check");
    let block = matrix_block();
    let readme = std::fs::read_to_string(README).expect("README.md is readable");
    let expected = replace_block(&readme, &block);
    if readme != expected {
        if check {
            eprintln!(
                "README.md harness matrix is stale — run `make docs-harness-matrix` and commit."
            );
            std::process::exit(1);
        }
        std::fs::write(README, expected).expect("README.md is writable");
        println!("updated README.md harness matrix");
    } else if !check {
        println!("README.md harness matrix is up to date");
    }
}
